package net.minecraft.world.entity;import net.minecraft.world.level.Level;public class Entity{public int tickCount,lastEvent;public java.util.UUID id=java.util.UUID.randomUUID();public Level world;public boolean alive=true;public double x,y,z;public Entity(Level l){world=l;}public Level level(){return world;}public boolean isAlive(){return alive;}public java.util.UUID getUUID(){return id;}public double distanceToSqr(Entity e){return (x-e.x)*(x-e.x)+(y-e.y)*(y-e.y)+(z-e.z)*(z-e.z);}public void handleEntityEvent(byte b){lastEvent=b;}}